const data = $input.item.json.propertyDetails;
const webhookData = $('Keep User Details').first().json;

let price = 'N/A';
if (data.price) {
  price = typeof data.price === 'number' ? `$${data.price.toLocaleString()}` : data.price;
}

let fullAddress = 'Unknown Address';
if (data.address) {
  if (typeof data.address === 'string') {
    fullAddress = data.address;
  } else {
    const street = data.address.streetAddress || '';
    const city = data.address.city || '';
    const state = data.address.state || '';
    fullAddress = `${street}, ${city}, ${state}`.trim();
  }
}

const beds = data.bedrooms || 'N/A';
const baths = data.bathrooms || 'N/A';
const sqft = data.livingArea || 'N/A';
let description = data.description || '';

const allImages = [];

// --- FIX APPLIED HERE ---
if (data.originalPhotos && Array.isArray(data.originalPhotos)) {
  data.originalPhotos.forEach((photo) => {
// --- END FIX ---
    let imageUrl = null;
    if (typeof photo === 'string') {
      imageUrl = photo;
    } else if (photo.mixedSources?.jpeg) {
      const jpegSources = photo.mixedSources.jpeg;
      imageUrl = jpegSources[jpegSources.length - 1]?.url;
    } else if (photo.url) {
      imageUrl = photo.url;
    }
    if (imageUrl) {
      allImages.push({ url: imageUrl, caption: photo.caption || '' });
    }
  });
}

if (data.images && Array.isArray(data.images)) {
  data.images.forEach((img) => {
    const imageUrl = typeof img === 'string' ? img : img.url;
    if (imageUrl) {
      allImages.push({ url: imageUrl, caption: img.caption || '' });
    }
  });
}

const priorityKeywords = ['kitchen', 'living', 'dining', 'bedroom', 'bath'];
const excludeKeywords = ['exterior', 'front', 'street'];
const interiorImages = [];
const otherImages = [];

allImages.forEach(img => {
  const caption = img.caption.toLowerCase();
  const isInterior = priorityKeywords.some(k => caption.includes(k));
  const isExterior = excludeKeywords.some(k => caption.includes(k));
  if (isInterior && !isExterior) {
    interiorImages.push(img);
  } else {
    otherImages.push(img);
  }
});

let selectedImages = [...interiorImages.slice(0, 2), ...otherImages.slice(0, 1)];

if (selectedImages.length === 0) {
  selectedImages = allImages.slice(0, 2);
}

const imageUrls = selectedImages.map(img => img.url);

if (imageUrls.length === 0) {
  throw new Error('No images found in API response!');
}

return {
  price: String(price),
  address: fullAddress,
  beds: String(beds),
  baths: String(baths),
  sqft: String(sqft),
  description: String(description).slice(0, 500),
  images: imageUrls,
  imageCount: imageUrls.length,
  name: webhookData.name,
  email: webhookData.email
};

const response = $input.item.json;
const content = response.choices[0].message.content;
const webhookData = $('Keep User Details').first().json;
const descriptions = content.split('\n').filter(line => line.trim().length > 10).slice(0, 2);
const propertyData = $('Parse RapidAPI Data').first().json;

const imageData = propertyData.images.map((imageUrl, index) => ({
  imageUrl,
  description: descriptions[index] || 'Beautiful property feature',
  index
}));

return imageData.map(item => ({
  ...propertyData,
  currentImage: item.imageUrl,
  currentDescription: item.description,
  imageIndex: item.index,
  name: webhookData.name,
  email: webhookData.email
}));

const gdriveFileId = $json.id;
const descriptionsNode = $('Generate Descriptions').first().json;
const kiePrompt = descriptionsNode.choices[0].message.content;
const propertyNode = $('Prepare Image Data').first().json;

console.log('=== MERGE GDRIVE INFO ===');
console.log('Property data:', JSON.stringify(propertyNode, null, 2));

return {
  gdriveFileId: gdriveFileId,
  gdrivePublicUrl: `https://drive.google.com/uc?export=download&id=${gdriveFileId}`,
  kiePrompt: kiePrompt,
  currentImage: propertyNode.currentImage,
  currentDescription: propertyNode.currentDescription,
  imageIndex: propertyNode.imageIndex,
  address: propertyNode.address,
  price: propertyNode.price,
  beds: propertyNode.beds,
  baths: propertyNode.baths,
  sqft: propertyNode.sqft,
  name: propertyNode.name,
  email: propertyNode.email
};

const apiResponse = $input.item.json;

if (apiResponse.code !== 200 || !apiResponse.data || !apiResponse.data.taskId) {
  throw new Error(`Kie.ai Task Creation Failed. Code: ${apiResponse.code || 'N/A'}, Msg: ${apiResponse.msg || 'No Task ID'}`);
}

const safePromptNode = $('safePrompt').first().json;
const fullPrompt = safePromptNode.safePrompt || "Prompt not available";

console.log('=== STORE TASK INFO ===');
console.log('Task ID:', apiResponse.data.taskId);
console.log('Address:', safePromptNode.address);
console.log('Email:', safePromptNode.email);

return {
  taskId: apiResponse.data.taskId,
  description: fullPrompt,
  imageUrl: safePromptNode.gdrivePublicUrl || "Image URL not available",
  gdriveFileId: safePromptNode.gdriveFileId || "",
  address: safePromptNode.address || "Address not available",
  price: safePromptNode.price || "N/A",
  beds: safePromptNode.beds || "N/A",
  baths: safePromptNode.baths || "N/A",
  sqft: safePromptNode.sqft || "N/A",
  name: safePromptNode.name || "Customer",
  email: safePromptNode.email || "",
  retryCount: 0
};

const statusResponse = $input.item.json;
let propertyData = $input.item.json;

if (!propertyData.address || propertyData.address === 'Address not available') {
  try {
    propertyData = $node['Store Task Info'].json;
    console.log('Retrieved from Store Task Info');
  } catch (e) {
    propertyData = $('Store Task Info').first().json;
  }
}

console.log('Property data:', propertyData.address, propertyData.email);

if (statusResponse.code === 422 || !statusResponse.data) {
  console.log('Status: Pending');
  return {
    status: 'pending',
    needsRetry: true,
    taskId: propertyData.taskId,
    description: propertyData.description,
    imageUrl: propertyData.imageUrl,
    address: propertyData.address,
    price: propertyData.price,
    beds: propertyData.beds,
    baths: propertyData.baths,
    sqft: propertyData.sqft,
    name: propertyData.name,
    email: propertyData.email,
    retryCount: propertyData.retryCount || 0
  };
}

if (statusResponse.data?.state?.includes('fail')) {
  throw new Error(`Video failed: ${statusResponse.data.state}`);
}

if (statusResponse.data?.state?.includes('success')) {
  console.log('Status: Complete!');
  return {
    status: 'complete',
    needsRetry: false,
    data: statusResponse.data,
    taskId: propertyData.taskId,
    description: propertyData.description,
    imageUrl: propertyData.imageUrl,
    address: propertyData.address,
    price: propertyData.price,
    beds: propertyData.beds,
    baths: propertyData.baths,
    sqft: propertyData.sqft,
    name: propertyData.name,
    email: propertyData.email
  };
}

console.log('Status: Processing');
return {
  status: 'processing',
  needsRetry: true,
  data: statusResponse.data,
  taskId: propertyData.taskId,
  description: propertyData.description,
  imageUrl: propertyData.imageUrl,
  address: propertyData.address,
  price: propertyData.price,
  beds: propertyData.beds,
  baths: propertyData.baths,
  sqft: propertyData.sqft,
  name: propertyData.name,
  email: propertyData.email,
  retryCount: propertyData.retryCount || 0
};

const MAX_RETRIES = 20;
const retryCount = $json.retryCount || 0;

if (retryCount >= MAX_RETRIES) {
  throw new Error(`Timeout after ${MAX_RETRIES} retries`);
}

return {
  taskId: $json.taskId,
  description: $json.description,
  imageUrl: $json.imageUrl,
  address: $json.address,
  price: $json.price,
  beds: $json.beds,
  baths: $json.baths,
  sqft: $json.sqft,
  name: $json.name,
  email: $json.email,
  retryCount: retryCount + 1,
  status: $json.status,
  needsRetry: $json.needsRetry
};

const statusData = $input.item.json;

let resultJson;
if (typeof statusData.data.resultJson === 'string') {
  resultJson = JSON.parse(statusData.data.resultJson);
} else {
  resultJson = statusData.data.resultJson;
}

const videoUrl = resultJson.resultUrls?.[0];

if (!videoUrl) {
  throw new Error('No video URL found');
}

const originalData = $node['Store Task Info'].json;

console.log('Video URL:', videoUrl);
console.log('Property data:', originalData.address);

return {
  videoUrl: videoUrl,
  imageUrl: originalData.imageUrl,
  description: originalData.description,
  address: originalData.address,
  price: originalData.price,
  beds: originalData.beds,
  baths: originalData.baths,
  sqft: originalData.sqft,
  name: originalData.name,
  email: originalData.email,
  taskId: originalData.taskId,
  gdriveFileId: originalData.gdriveFileId
};

const videos = items.map((item, index) => ({
  videoUrl: item.json.videoUrl,
  description: item.json.description || `Video ${index + 1}`,
  clipNumber: index + 1,
  gdriveFileId: item.json.gdriveFileId
}));

const firstItem = items[0].json;

if (videos.length === 0 || !videos[0].videoUrl) {
  throw new Error('No video URLs found');
}

console.log('Videos:', videos.map(v => v.videoUrl));

return {
  success: true,
  property: {
    address: firstItem.address,
    price: firstItem.price,
    beds: firstItem.beds,
    baths: firstItem.baths,
    sqft: firstItem.sqft,
    name: firstItem.name,
    email: firstItem.email
  },
  videos: videos,
  videoCount: videos.length,
  video1Url: videos[0]?.videoUrl || '',
  video2Url: videos[1]?.videoUrl || '',
  gdriveFileIds: videos.map(v => v.gdriveFileId),
  cost: {
    total: videos.length * 0.15,
    perVideo: 0.15
  },
  processingTime: new Date().toISOString()
};
